package com.example.techfix.ui;
import android.view.*; import android.widget.TextView; import androidx.recyclerview.widget.RecyclerView; import com.example.techfix.R; import com.example.techfix.data.entity.DeviceCategory; import java.util.List;
public class CategoryAdapter extends RecyclerView.Adapter<CategoryAdapter.ViewHolder>{ public interface Listener{void onClick(DeviceCategory c);} private final List<DeviceCategory> list; private final Listener listener; public CategoryAdapter(List<DeviceCategory> l,Listener x){list=l;listener=x;} public static class ViewHolder extends RecyclerView.ViewHolder{TextView name;ViewHolder(View v){super(v);name=v.findViewById(R.id.tvCategoryName);}} @Override public ViewHolder onCreateViewHolder(ViewGroup p,int t){return new ViewHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_category,p,false));} @Override public void onBindViewHolder(ViewHolder h,int pos){DeviceCategory c=list.get(pos);h.name.setText(c.getName());h.itemView.setOnClickListener(v->listener.onClick(c));} @Override public int getItemCount(){return list.size();}}
